create schema if not exists auth;
create schema if not exists private;
create table auth.users(id uuid primary key);
do $$ begin if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if; end $$;
create table public.profiles(id uuid primary key references auth.users(id), prenom text not null);
create table public.suspensions(user_id uuid primary key);
create table public.blocages(user_id uuid not null,cible uuid not null);
create table public.messages(id bigint generated always as identity primary key,de uuid not null,a uuid not null,texte text not null default '');
create table public.message_receipts(message_id bigint primary key,sender_id uuid not null,recipient_id uuid not null,delivered_at timestamptz,read_at timestamptz);
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create or replace function private.is_suspended(p_user uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.suspensions where user_id=p_user) $$;
create or replace function private.is_blocked_with(p_other uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.blocages b where (b.user_id=(select auth.uid()) and b.cible=p_other) or (b.user_id=p_other and b.cible=(select auth.uid()))) $$;
alter table public.messages enable row level security;
alter table public.message_receipts enable row level security;
create policy "message participants" on public.messages for select to authenticated using (de=auth.uid() or a=auth.uid());
create policy "participants read message receipts" on public.message_receipts for select to authenticated using (sender_id=auth.uid() or recipient_id=auth.uid());
create policy "recipient records delivery" on public.message_receipts for insert to authenticated with check (recipient_id=auth.uid() and exists(select 1 from public.messages m where m.id=message_id and m.de=sender_id and m.a=recipient_id));
create policy "recipient marks read" on public.message_receipts for update to authenticated using (recipient_id=auth.uid()) with check (recipient_id=auth.uid() and exists(select 1 from public.messages m where m.id=message_id and m.de=sender_id and m.a=recipient_id));
grant usage on schema auth,private,public to authenticated;
grant execute on function auth.uid(),private.is_suspended(uuid),private.is_blocked_with(uuid) to authenticated;
grant select on public.messages,public.profiles to authenticated;
grant select,insert on public.message_receipts to authenticated;
